    // Initialize the counts for the common letters and the total lengths
    int common = 0;
    int len1 = word1.length();
    int len2 = word2.length();

    // Loop through the characters of the two words and count the common letters
    for (int i = 0; i < len1; i++) {
        for (int j = 0; j < len2; j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                common++;
                break;
            }
        }
    }

    // Calculate the approximate value as a reduced fraction
    int gcd = getGCD(len1, len2);
    int reduced1 = common / gcd;
    int reduced2 = (len1 * len2) / (gcd * gcd);
    String reduced = reduced1 + "/" + reduced2;

    // Return the approximate value as a string
    return "appx(" + word1 + ", " + word2 + ") = " + reduced;
}

