public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] dist = new int[n];
  Arrays.fill(dist, -1);
  dist[0] = 0;
  int time = 0;
  Queue<Integer> q = new LinkedList<>();
  q.add(0);
  while (!q.isEmpty()) {
    int node = q.poll();
    for (int i = 0; i < edges.length; i++) {
      if (edges[i][0] == node && dist[edges[i][1]] == -1) {
        dist[edges[i][1]] = dist[node] + 1;
        if (hasApple[edges[i][1]]) {
          time++;
        }
        q.add(edges[i][1]);
      }
    }
  }
  return time;
}

