public int maxUniqueSplit(String s) {
    // Maintain a set to keep track of unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();
    // Keep track of the current substring
    StringBuilder currentSubstring = new StringBuilder();
    // Keep track of the maximum number of unique substrings
    int maxUniqueSubstrings = 0;

    for (char c : s.toCharArray()) {
        // If the current character is not already in the set, add it to the current substring
        if (!uniqueSubstrings.contains(currentSubstring.toString())) {
            currentSubstring.append(c);
        } else {
            // If the current character is already in the set, add it to the unique substrings
            uniqueSubstrings.add(currentSubstring.toString());
            maxUniqueSubstrings = Math.max(maxUniqueSubstrings, uniqueSubstrings.size());
            currentSubstring = new StringBuilder(c);
        }
    }

    // Add the last substring to the set
    uniqueSubstrings.add(currentSubstring.toString());
    maxUniqueSubstrings = Math.max(maxUniqueSubstrings, uniqueSubstrings.size());

    return maxUniqueSubstrings;
}

