            result.add(String.valueOf(i));
        } else {
            result.add(String.valueOf(i) + "0" + String.valueOf(mirror));
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
  // Check if the points are colinear
  if (points.length < 3) {
    return false;
  }
  if (points[0][0] == points[1][0] && points[1][0] == points[2][0]) {
    return false;
  }

  // Calculate the determinant of the matrix formed by the three points
  int det = (points[1][1] - points[0][1]) * (points[2][0] - points[1][0])
    - (points[1][0] - points[0][0]) * (points[2][1] - points[1][1]);

  // If the determinant is zero, the points are colinear
  if (det == 0) {
    return false;
  }

  // If the determinant is positive, the points are counterclockwise ordered
  // If the determinant is negative, the points are clockwise ordered
  return det > 0;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        dp[i] = min;
        if (min == dp[i2] * 2) i2++;
        if (min == dp[i3] * 3) i3++;
        if (min == dp[i5] * 5) i5++;
    }
    return dp[n];
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    for (int i = 0; i < s.length(); i++) {
        int start = i;
        while (start < s.length() && s.charAt(start) == s.charAt(i)) {
            start++;
        }
        int energy = start - i;
        if (energy > maxEnergy) {
            maxEnergy = energy;
        }
        i = start - 1;
    }
    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (!uniqueNums.contains(num)) {
            uniqueNums.add(num);
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        count++;
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        String reversedWord = new StringBuilder(word).reverse().toString();
        result.append(reversedWord).append(" ");
    }
    return result.toString().trim();
}
